// 自动从Material Symbols字体(fontTools提取)+Stitch设计稿(potrace描边)生成的
// 图标形状数据——纯路径数据，不含颜色/发光效果(那两层分别在EffectIcon.tsx的CSS
// 和调用方决定，见design-assets/icons/summer-fireworks-icon-effects/的设计稿)。
// viewBox里9个Material Symbols图标的偏移量不是随手写的：字体字形的几何外框
// (bounding box)本身严格居中在960x960格子里，但有几个图标(payments/person/
// history/arrow_back/bar_chart)有细长装饰笔画把外框撑大、却不贡献视觉重量，
// 导致图标本身看起来偏移——这几个offset是栅格化后腐蚀掉细笔画、只留厚实主体
// 再算像素质心得出来的，让图标在视觉上真正居中，不只是数学居中(B-XX)
export type IconKey =
  | 'language'
  | 'payments'
  | 'person'
  | 'history'
  | 'info'
  | 'menu'
  | 'arrow_back'
  | 'bar_chart'
  | 'currency_exchange'
  | 'book'
  | 'palette'
  | 'settings'
  | 'restart_alt'

export interface IconGlyph {
  viewBox: string
  path: string
  /** Material Symbols字体坐标系Y轴朝上(跟SVG常规Y轴朝下相反)，渲染时需要一次
   * Y轴翻转(见AppIcon.tsx)才能正常显示；book图标是直接从设计稿potrace描边得到
   * 的普通SVG路径，不需要这个翻转 */
  flipY: boolean
}

